From 58a4b540ec32a84fbe28ad992c9a8e8efd2c61e3 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Thu, 26 Nov 2026 23:08:55 +0100
Subject: [PATCH] containments/desktop: list Applications, Fonts and Tags as
 locations

Showing applications:/, fonts:/ or tags:/ in Folder View was only
possible by typing the URL as a custom location, so few people knew
about it. List these locations after the places in the location combo.

BUG: 360355
---
 .../desktop/plugins/folder/placesmodel.cpp    | 45 ++++++++++++++++---
 .../desktop/plugins/folder/placesmodel.h      |  4 ++
 2 files changed, 44 insertions(+), 5 deletions(-)

diff --git a/containments/desktop/plugins/folder/placesmodel.cpp b/containments/desktop/plugins/folder/placesmodel.cpp
index 91b14a37b6..7eb348fd73 100644
--- a/containments/desktop/plugins/folder/placesmodel.cpp
+++ b/containments/desktop/plugins/folder/placesmodel.cpp
@@ -6,19 +6,45 @@

 #include "placesmodel.h"

+#include <QConcatenateTablesProxyModel>
+#include <QStandardItemModel>
 #include <QStandardPaths>

 #include <KFilePlacesModel>
+#include <KLocalizedString>
 #include <KPluginMetaData>
+#include <KProtocolInfo>

 PlacesModel::PlacesModel(QObject *parent)
     : QSortFilterProxyModel(parent)
     , m_sourceModel(new KFilePlacesModel(this))
+    , m_specialLocationsModel(new QStandardItemModel(this))
+    , m_concatModel(new QConcatenateTablesProxyModel(this))
 {
     connect(m_sourceModel, &KFilePlacesModel::rowsInserted, this, &PlacesModel::placesChanged);
     connect(m_sourceModel, &KFilePlacesModel::rowsRemoved, this, &PlacesModel::placesChanged);

-    setSourceModel(m_sourceModel);
+    const struct {
+        QString text;
+        QUrl url;
+    } specialLocations[] = {
+        {i18nc("@item:inlistbox", "Applications"), QUrl(QStringLiteral("applications:/"))},
+        {i18nc("@item:inlistbox", "Fonts"), QUrl(QStringLiteral("fonts:/"))},
+        {i18nc("@item:inlistbox", "Tags"), QUrl(QStringLiteral("tags:/"))},
+    };
+
+    for (const auto &location : specialLocations) {
+        if (KProtocolInfo::isKnownProtocol(location.url)) {
+            auto item = new QStandardItem(location.text);
+            item->setData(location.url, KFilePlacesModel::UrlRole);
+            m_specialLocationsModel->appendRow(item);
+        }
+    }
+
+    m_concatModel->addSourceModel(m_sourceModel);
+    m_concatModel->addSourceModel(m_specialLocationsModel);
+
+    setSourceModel(m_concatModel);

     setDynamicSortFilter(true);
 }
@@ -59,7 +85,7 @@ void PlacesModel::setShowDesktopEntry(bool showDesktopEntry)

 QString PlacesModel::urlForIndex(int idx) const
 {
-    return m_sourceModel->url(mapToSource(index(idx, 0))).toString();
+    return index(idx, 0).data(KFilePlacesModel::UrlRole).toUrl().toString();
 }

 int PlacesModel::indexForUrl(const QString &url) const
@@ -68,7 +94,7 @@ int PlacesModel::indexForUrl(const QString &url) const
     QModelIndex idx;

     for (int i = 0; i < rowCount(); i++) {
-        if (_url == m_sourceModel->url(mapToSource(index(i, 0)))) {
+        if (_url == index(i, 0).data(KFilePlacesModel::UrlRole).toUrl()) {
             idx = index(i, 0);
             break;
         }
@@ -83,10 +109,19 @@ int PlacesModel::indexForUrl(const QString &url) const

 bool PlacesModel::filterAcceptsRow(int sourceRow, const QModelIndex &sourceParent) const
 {
-    const QModelIndex index = m_sourceModel->index(sourceRow, 0, sourceParent);
+    const QModelIndex index = m_concatModel->mapToSource(m_concatModel->index(sourceRow, 0, sourceParent));
+
+    if (index.model() != m_sourceModel) {
+        return true;
+    }
+
+    const QUrl url = index.data(KFilePlacesModel::UrlRole).toUrl();
+
+    if (!m_specialLocationsModel->match(m_specialLocationsModel->index(0, 0), KFilePlacesModel::UrlRole, url, 1, Qt::MatchExactly).isEmpty()) {
+        return false;
+    }

     if (!m_showDesktopEntry) {
-        const QUrl url = index.data(KFilePlacesModel::UrlRole).toUrl();
         const QUrl desktopUrl = QUrl::fromLocalFile(QStandardPaths::writableLocation(QStandardPaths::DesktopLocation));
         if (url == desktopUrl) {
             return false;
diff --git a/containments/desktop/plugins/folder/placesmodel.h b/containments/desktop/plugins/folder/placesmodel.h
index bc5fb15c24..ea306023c9 100644
--- a/containments/desktop/plugins/folder/placesmodel.h
+++ b/containments/desktop/plugins/folder/placesmodel.h
@@ -10,6 +10,8 @@
 #include <qqmlregistration.h>

 class KFilePlacesModel;
+class QConcatenateTablesProxyModel;
+class QStandardItemModel;

 class PlacesModel : public QSortFilterProxyModel
 {
@@ -41,5 +43,7 @@ protected:

 private:
     KFilePlacesModel *const m_sourceModel;
+    QStandardItemModel *const m_specialLocationsModel;
+    QConcatenateTablesProxyModel *const m_concatModel;
     bool m_showDesktopEntry = true;
 };
